mapper.update:
UPDATE AI_EVAL_RUN
   SET STATUS = 'RUNNING'
     , STARTED_AT = now()
     , WORK_DIR = #{workDir}
 WHERE RUN_ID = #{runId}
   AND STATUS = 'QUEUED'

UPDATE AI_EVAL_RUN
   SET STATUS = #{status}
     , PASSED = #{passed, jdbcType=INTEGER}
     , TOTAL = #{total, jdbcType=INTEGER}
     , CHECKS_JSON = CAST(#{checksJson, jdbcType=VARCHAR} AS JSONB)
     , ANSWER_JSON = CAST(#{answerJson, jdbcType=VARCHAR} AS JSONB)
     , FAILURE = #{failure, jdbcType=VARCHAR}
     , DURATION_MS = #{durationMs, jdbcType=BIGINT}
     , ROUNDS = #{rounds, jdbcType=INTEGER}
     , TOOL_CALLS = #{toolCalls, jdbcType=INTEGER}
     , TOOLS_JSON = CAST(#{toolsJson, jdbcType=VARCHAR} AS JSONB)
     , PROMPT_TOKENS = #{promptTokens, jdbcType=BIGINT}
     , COMPLETION_TOKENS = #{completionTokens, jdbcType=BIGINT}
     , WORK_DIR = COALESCE(#{workDir, jdbcType=VARCHAR}, WORK_DIR)
     , FINISHED_AT = now()
 WHERE RUN_ID = #{runId}

mapper.select:

 FROM AI_EVAL_RUN

   CASE_ID = #{caseId}

ORDER BY CREATED_AT DESC, RUN_ID
LIMIT #{limit}
